mapper.sql:
WHERE DEL_YN = 'N'
   AND CATEGORY_CD = #{categoryCd}   
           AND TYPE_CD = #{typeCd}           
 AND SIDO_REGION_CD = #{sidoRegionCd} 
         AND TITLE LIKE CONCAT('%', #{keyword}, '%')

mapper.update:
UPDATE CONTENT_REGION
   SET EXPOSE_YN = #{exposeYn},
       MDFCN_DT  = UTC_TIMESTAMP(6),
       MDFR_SN   = #{mdfrSn}
 WHERE CONTENT_REGION_SN = #{contentRegionSn}
   AND DEL_YN = 'N'

UPDATE CONTENT_REGION
   SET DEL_YN   = 'Y',
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN  = #{mdfrSn}
 WHERE CONTENT_REGION_SN = #{contentRegionSn}
   AND DEL_YN = 'N'
